// @input kind: string - Type of script
// @input title: string - Script title
// @input subtitle: string - Optional subtitle
// @input genre: string[] - Genre array
// @input visualizationStyle: string - Visual style for assets
// @input logline: string - Story logline
// @input tone: string[] - Tonal qualities
// @input runtimeMinutes: number - Target runtime
// @input authorName: string - Author name
// @output scriptInput: object - The ScriptGeneratorInput object
// @output script: object - The ScriptDocument structure
// @output scriptId: string - Generated script ID
// @output title: string - Script title (pass-through)
// @output visualizationStyle: string - Visual style (pass-through)
// @output genre: string[] - Genre array (pass-through)
// @output logline: string - Logline (pass-through)
// @output tone: string[] - Tone array (pass-through)

const kind = inputs.kind || 'short-film';
const title = inputs.title || 'Untitled';
const subtitle = inputs.subtitle || '';
const genre = Array.isArray(inputs.genre) ? inputs.genre : (inputs.genre ? [inputs.genre] : ['drama']);
const visualizationStyle = inputs.visualizationStyle || 'cinematic realism';
const logline = inputs.logline || '';
const tone = Array.isArray(inputs.tone) ? inputs.tone : [];
const runtimeMinutes = inputs.runtimeMinutes || 10;
const authorName = inputs.authorName || 'Anonymous';

// Build the input object
const scriptInput = {
  kind,
  title,
  subtitle: subtitle || undefined,
  genre,
  visualizationStyle,
  logline: logline || undefined,
  tone: tone.length ? tone : undefined,
  runtimeMinutes,
  author: [{ name: authorName, role: 'writer' }]
};

// Generate unique IDs
const scriptId = `script_${title.toLowerCase().replace(/[^a-z0-9]/g, '_')}_${Date.now()}`;

// Build metadata
const metadata = {
  title,
  subtitle: subtitle || undefined,
  logline: logline || undefined,
  author: [{ name: authorName, role: 'writer' }],
  genre,
  tone: tone.length ? tone : undefined,
  runtimeMinutes,
  draftDate: new Date().toISOString().split('T')[0],
  version: '1.0'
};

// Create the script document structure
const script = {
  id: scriptId,
  kind,
  metadata,
  cast: [],
  locations: [],
  sections: []
};

return {
  scriptInput,
  script,
  scriptId,
  title,
  visualizationStyle,
  genre,
  logline,
  tone
};

// @input script: object - The ScriptDocument to populate
// @input title: string - Script title
// @input genre: string[] - Genre array
// @input logline: string - Story logline
// @input visualizationStyle: string - Visual style
// @output script: object - Updated ScriptDocument with cast/locations/sections
// @output cast: object[] - Character definitions
// @output locations: object[] - Location definitions
// @output sections: object[] - Script sections
// @output shotElements: object[] - Extracted shot elements for previs
// @output title: string - Script title (pass-through)
// @output visualizationStyle: string - Visual style (pass-through)

const script = JSON.parse(JSON.stringify(inputs.script));
const title = inputs.title;
const genre = inputs.genre;
const logline = inputs.logline;
const visualizationStyle = inputs.visualizationStyle;

// Helper to generate IDs
const genId = (prefix, name) => `${prefix}_${name.toLowerCase().replace(/[^a-z0-9]/g, '_')}`;

// Placeholder cast - in real use, LLM would generate based on logline/genre
const cast = [
  {
    id: genId('char', 'protagonist'),
    name: 'PROTAGONIST',
    displayName: 'The Protagonist',
    description: `Main character of ${title}`,
    ageRange: '25-35',
    gender: 'any'
  }
];

// Placeholder locations
const locations = [
  {
    id: genId('loc', 'main_setting'),
    name: 'MAIN SETTING',
    description: `Primary location for ${title}`,
    recurring: true
  }
];

// Generate sections with scenes
const sections = [
  {
    id: 'scene_1',
    type: 'scene',
    order: 1,
    sceneNumber: '1',
    heading: {
      prefix: 'EXT',
      location: locations[0].name,
      timeOfDay: 'DAY'
    },
    synopsis: `Opening scene of ${title}`,
    beats: [
      {
        id: 'shot_1_1',
        type: 'shot',
        text: 'ESTABLISHING SHOT - The setting comes into view.'
      },
      {
        id: 'action_1_1',
        type: 'action',
        text: `${cast[0].name} enters the scene.`
      },
      {
        id: 'dialogue_1_1',
        type: 'dialogue',
        characterId: cast[0].id,
        characterName: cast[0].name,
        lines: ['(First line of dialogue)']
      }
    ],
    locationId: locations[0].id,
    estimatedDurationSeconds: 60
  }
];

// Update script with generated content
script.cast = cast;
script.locations = locations;
script.sections = sections;

// Extract all shot elements for previs generation
const shotElements = [];
sections.forEach(section => {
  if (section.type === 'scene' && section.beats) {
    section.beats.forEach(beat => {
      if (beat.type === 'shot') {
        shotElements.push({
          shotId: beat.id,
          shotText: beat.text,
          sceneId: section.id,
          locationId: section.locationId,
          characterIds: cast.map(c => c.id)
        });
      }
    });
  }
});

return {
  script,
  cast,
  locations,
  sections,
  shotElements,
  title,
  visualizationStyle
};

// @input cast: object[] - Character definitions
// @input title: string - Script title (for collection name)
// @input visualizationStyle: string - Visual style for prompts
// @output characterAssets: object[] - Character headshot VisualAsset objects

const cast = inputs.cast || [];
const title = inputs.title;
const visualizationStyle = inputs.visualizationStyle;

const characterAssets = cast.map(character => {
  const assetId = `asset_headshot_${character.id}`;

  // Build descriptive prompt from character data
  const promptParts = [
    'Portrait headshot of',
    character.displayName || character.name,
  ];

  if (character.description) {
    promptParts.push(character.description);
  }
  if (character.ageRange) {
    promptParts.push(`age ${character.ageRange}`);
  }
  promptParts.push(visualizationStyle);

  return {
    id: assetId,
    type: 'character-headshot',
    name: `${character.displayName || character.name} Headshot`,
    collectionName: title,
    prompt: promptParts.join(', '),
    visualizationStyle,
    characterId: character.id,
    status: 'planned',
    aspectRatio: '3:4',
    tags: ['character', 'headshot', character.name.toLowerCase()]
  };
});

return { characterAssets };

// @input locations: object[] - Location definitions
// @input title: string - Script title (for collection name)
// @input visualizationStyle: string - Visual style for prompts
// @output locationAssets: object[] - Location landscape VisualAsset objects

const locations = inputs.locations || [];
const title = inputs.title;
const visualizationStyle = inputs.visualizationStyle;

const locationAssets = locations.map(location => {
  const assetId = `asset_landscape_${location.id}`;

  // Build descriptive prompt from location data
  const promptParts = [
    location.name,
    location.description || 'establishing view'
  ];
  promptParts.push(visualizationStyle);

  return {
    id: assetId,
    type: 'landscape',
    name: `${location.name} Landscape`,
    collectionName: title,
    prompt: promptParts.join(', '),
    visualizationStyle,
    locationId: location.id,
    status: 'planned',
    aspectRatio: '16:9',
    tags: ['location', 'landscape', 'establishing']
  };
});

return { locationAssets };

// @input shotElements: object[] - Shot elements extracted from scenes
// @input title: string - Script title (for collection name)
// @input visualizationStyle: string - Visual style for prompts
// @input locations: object[] - Location definitions for context
// @input cast: object[] - Character definitions for context
// @output previsAssets: object[] - Previs-frame VisualAsset objects
// @output shotElements: object[] - Shot elements (pass-through)

const shotElements = inputs.shotElements || [];
const title = inputs.title;
const visualizationStyle = inputs.visualizationStyle;
const locations = inputs.locations || [];
const cast = inputs.cast || [];

// Create a lookup for location names
const locationMap = {};
locations.forEach(loc => { locationMap[loc.id] = loc; });

// Create a lookup for character names
const characterMap = {};
cast.forEach(char => { characterMap[char.id] = char; });

const previsAssets = shotElements.map((shot, index) => {
  const assetId = `asset_previs_${shot.sceneId}_${shot.shotId}`;

  // Build prompt from shot text and context
  const location = locationMap[shot.locationId];
  const promptParts = [
    shot.shotText,
    location ? `at ${location.name}` : '',
    visualizationStyle
  ].filter(Boolean);

  return {
    id: assetId,
    type: 'previs-frame',
    name: `${shot.sceneId} ${shot.shotId} Previs`,
    collectionName: title,
    prompt: promptParts.join(', '),
    visualizationStyle,
    sceneId: shot.sceneId,
    shotElementId: shot.shotId,
    locationId: shot.locationId,
    status: 'planned',
    aspectRatio: '16:9',
    tags: ['previs', 'frame', shot.sceneId]
  };
});

return { previsAssets, shotElements };

// @input title: string - Script title (must match collection name)
// @input characterAssets: object[] - Character headshot assets
// @input locationAssets: object[] - Location landscape assets
// @input previsAssets: object[] - Previs-frame assets
// @output assetCollection: object - The complete AssetCollection

const title = inputs.title;
const characterAssets = inputs.characterAssets || [];
const locationAssets = inputs.locationAssets || [];
const previsAssets = inputs.previsAssets || [];

// Combine all assets
const allAssets = [
  ...characterAssets,
  ...locationAssets,
  ...previsAssets
];

// Create the AssetCollection
const assetCollection = {
  id: `assets_${title.toLowerCase().replace(/[^a-z0-9]/g, '_')}`,
  name: title, // Must equal script.metadata.title
  description: `Visual assets for ${title}`,
  assets: allAssets
};

return { assetCollection };

// @input title: string - Script title (for collection name)
// @input scriptId: string - Script document ID
// @input shotElements: object[] - Shot elements from scenes
// @input previsAssets: object[] - Previs-frame assets
// @input locations: object[] - Location definitions
// @input cast: object[] - Character definitions
// @output previsualizations: object - The PrevisualizationPlan

const title = inputs.title;
const scriptId = inputs.scriptId;
const shotElements = inputs.shotElements || [];
const previsAssets = inputs.previsAssets || [];
const locations = inputs.locations || [];
const cast = inputs.cast || [];

// Create lookup for previs assets by shot
const previsAssetMap = {};
previsAssets.forEach(asset => {
  const key = `${asset.sceneId}_${asset.shotElementId}`;
  previsAssetMap[key] = asset;
});

// Generate PrevisualizationShots
const shots = shotElements.map((shot, index) => {
  const key = `${shot.sceneId}_${shot.shotId}`;
  const asset = previsAssetMap[key];

  // Determine camera intent from shot text
  let cameraIntent = 'narrative';
  const shotTextLower = shot.shotText.toLowerCase();
  if (shotTextLower.includes('establishing') || shotTextLower.includes('wide')) {
    cameraIntent = 'establishing';
  } else if (shotTextLower.includes('close') || shotTextLower.includes('cu')) {
    cameraIntent = 'close-up';
  } else if (shotTextLower.includes('medium') || shotTextLower.includes('ms')) {
    cameraIntent = 'medium';
  }

  // Determine composition
  let composition = 'standard';
  if (shotTextLower.includes('wide')) composition = 'very wide';
  if (shotTextLower.includes('close')) composition = 'tight';
  if (shotTextLower.includes('two-shot')) composition = 'two-shot';

  return {
    id: `previs_${index + 1}`,
    sceneId: shot.sceneId,
    shotElementId: shot.shotId,
    shotText: shot.shotText,
    order: index + 1,
    locationId: shot.locationId,
    characterIds: shot.characterIds,
    description: `Previs frame for: ${shot.shotText}`,
    cameraIntent,
    composition,
    lighting: 'natural',
    durationSeconds: 3,
    assetId: asset ? asset.id : null // Links to the previs-frame asset
  };
});

// Create the PrevisualizationPlan
const previsualizations = {
  scriptId,
  collectionName: title,
  shots
};

return { previsualizations };

// @input scriptInput: object - The original ScriptGeneratorInput
// @input script: object - The ScriptDocument
// @input assetCollection: object - The AssetCollection
// @input previsualizations: object - The PrevisualizationPlan
// @output generatedPackage: object - The complete GeneratedScriptPackage
// @output validation: object - Validation results with errors/warnings/stats

const scriptInput = inputs.scriptInput;
const script = inputs.script;
const assetCollection = inputs.assetCollection;
const previsualizations = inputs.previsualizations;

// Validation results
const validationErrors = [];
const validationWarnings = [];

// Rule 1: assets.name must equal script.metadata.title
if (assetCollection.name !== script.metadata.title) {
  validationErrors.push(`Asset collection name '${assetCollection.name}' does not match script title '${script.metadata.title}'`);
}

// Rule 2: Every named character must have a headshot
const characterIds = new Set(script.cast.map(c => c.id));
const headshotCharacterIds = new Set(
  assetCollection.assets
    .filter(a => a.type === 'character-headshot')
    .map(a => a.characterId)
);
characterIds.forEach(charId => {
  if (!headshotCharacterIds.has(charId)) {
    validationErrors.push(`Missing headshot asset for character: ${charId}`);
  }
});

// Rule 3: Every location must have a landscape
const locationIds = new Set(script.locations.map(l => l.id));
const landscapeLocationIds = new Set(
  assetCollection.assets
    .filter(a => a.type === 'landscape')
    .map(a => a.locationId)
);
locationIds.forEach(locId => {
  if (!landscapeLocationIds.has(locId)) {
    validationErrors.push(`Missing landscape asset for location: ${locId}`);
  }
});

// Rule 4: Every shot element must have a previs
const shotElementIds = [];
script.sections.forEach(section => {
  if (section.type === 'scene' && section.beats) {
    section.beats.forEach(beat => {
      if (beat.type === 'shot') {
        shotElementIds.push(beat.id);
      }
    });
  }
});
const previsAssetShotIds = new Set(
  assetCollection.assets
    .filter(a => a.type === 'previs-frame')
    .map(a => a.shotElementId)
);
shotElementIds.forEach(shotId => {
  if (!previsAssetShotIds.has(shotId)) {
    validationErrors.push(`Missing previs-frame asset for shot: ${shotId}`);
  }
});

// Rule 5: Every PrevisualizationShot.assetId must point to a previs-frame
const previsFrameIds = new Set(
  assetCollection.assets
    .filter(a => a.type === 'previs-frame')
    .map(a => a.id)
);
previsualizations.shots.forEach(shot => {
  if (!shot.assetId || !previsFrameIds.has(shot.assetId)) {
    validationErrors.push(`PrevisualizationShot ${shot.id} has invalid assetId: ${shot.assetId}`);
  }
});

// Build the final package
const generatedPackage = {
  input: scriptInput,
  script,
  assets: assetCollection,
  previsualizations
};

// Add validation metadata
const validation = {
  valid: validationErrors.length === 0,
  errors: validationErrors,
  warnings: validationWarnings,
  stats: {
    castCount: script.cast.length,
    locationCount: script.locations.length,
    sectionCount: script.sections.length,
    totalAssets: assetCollection.assets.length,
    headshotAssets: assetCollection.assets.filter(a => a.type === 'character-headshot').length,
    landscapeAssets: assetCollection.assets.filter(a => a.type === 'landscape').length,
    previsAssets: assetCollection.assets.filter(a => a.type === 'previs-frame').length,
    previsShots: previsualizations.shots.length
  }
};

return {
  generatedPackage,
  validation
};
